mapper.select:
select pro.P_Name as pName, pro.P_Code as pCode, pro.P_Approve_Budget as pApproveBudget, pro.P_Category as pCategory, pro.P_Build_Model as pBuildModel, pro.p_Competent_Department as pCompetentDepartment, d.D_Name as pCompetentDepartmentName, sec.Sec_Name as secName, sec.Sec_Bidding_Type as secBiddingType, sec.Sec_Place as secPlace, sec.Sec_Remark as secRemark, sec.Sec_Organize_Form as secOrganizeForm, sec.Sec_Evaluate_Separation as secEvaluateSeparation, sec.Sec_Quali_Review as secQualiReview, sec.Sec_Bid_Time as secBidTime, sec.Sec_Loaction as secLoaction, sec.Sec_Investors_Quali as secInvestorsQuali, case when sbp.is_new = 1 then sec.Sec_Type else mn.Sec_Type end as secType, sec.Sec_Section_Classify as secSectionClassify, sbp.is_new as isNew, c1.C_Name as secTendereeName, c2.C_Name as secAgencyName, c3.C_Name as srCompanyName, mn.* from Sec_Selection_Record mn left join Pre_Project pro on pro.P_Id = mn.P_Id left join Sec_Info sec on sec.Sec_Id = mn.Sec_Id left join Sec_Bidding_Plan sbp on sbp.Bp_Id = sec.Bp_Id left join SYS_Company c1 on c1.C_Id = sec.Sec_Tenderee left join SYS_Company c2 on c2.C_Id = sec.Sec_Agency left join SYS_Company c3 on c3.C_Id = mn.Sr_Company left join SYS_Department d on d.D_Id = pro.p_Competent_Department ${params.authSql}
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Sr_Create_Time desc

select pro.P_Name as pName, pro.P_Code as pCode, pro.P_Approve_Budget as pApproveBudget, sec.Sec_Name as secName, sec.Sec_Bidding_Type as secBiddingType, sec.Sec_Place as secPlace, sec.Sec_Remark as secRemark, sec.Sec_Organize_Form as secOrganizeForm, sec.Sec_Evaluate_Separation as secEvaluateSeparation, sec.Sec_Quali_Review as secQualiReview, sec.Sec_Bid_Time as secBidTime, sec.Sec_Loaction as secLoaction, sec.Sec_Investors_Quali as secInvestorsQuali, sd.D_Function as dFunction, sd.D_Scope as dScope, sd.D_Executive_Standard as dExecutiveStandard, sd.D_Amount as dAmount, c1.C_Name as secTendereeName, c2.C_Name as secAgencyName, sr.state as srState, mn.state as esState, mn.*, sr.* from Sec_Selection_Record sr left join Sec_Expert_Select mn on mn.id=Sr.Es_Id left join Pre_Project pro on pro.P_Id = mn.P_Id left join Sec_Info sec on sec.Sec_Id = mn.Sec_Id left join SYS_Company c1 on c1.C_Id = sec.Sec_Tenderee left join SYS_Company c2 on c2.C_Id = sec.Sec_Agency left join Sec_Document sd on sd.Sec_Id = sec.Sec_Id and sd.D_State = 7
and sr.Te_Id = #{params.teId}
and mn.P_Id=#{params.pId}
and sr.State=#{params.state}
and likePname(#{params.pName},pro.P_Id)=true
and INSTR(pro.P_Name,#{params.pName})
and INSTR(sec.Sec_Name,#{params.secName})
and INSTR(sr.Sr_Create_Uname,#{params.createUname})
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Create_Time DESC

select * from Sec_Selection_Record

    
        and Sec_Id = #{params.secId}
    
    
        and State = #{params.dState}
    
    
        and sd.Te_Id = #{params.teId}
